import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

@Injectable({
    providedIn: 'root'
})
export class ErrorService {

    private apiError$$ = new BehaviorSubject(null);
    public apiError$ = this.apiError$$.asObservable();

    constructor() { }

    setError(error: any) {
        this.apiError$$.next(error);
        console.log(error);
    }
}
